import {validGuestEmail} from './invitation-email.js';
export function cleanGuests(value){return Array.isArray(value)?value.slice(0,100).filter(guest=>guest&&typeof guest.name==='string'&&guest.name.trim()).map(guest=>({id:typeof guest.id==='string'?guest.id.slice(0,50):crypto.randomUUID(),name:guest.name.trim().slice(0,80),email:validGuestEmail(guest.email)?String(guest.email).trim():'',allowedCount:Math.max(1,Math.min(10,Math.floor(Number(guest.allowedCount)||1))),status:['accepted','declined'].includes(guest.status)?guest.status:'invited',attendingCount:Math.max(0,Math.min(10,Math.floor(Number(guest.attendingCount)||0)))})):[];}
export function initGuests({getState,onChange,onPreview,onDownload,onEmail,toast}){
 const panel=document.createElement('details');panel.className='guest-manager options-panel';panel.innerHTML='<summary>Quem vai celebrar com vocês? <span class="guest-count"></span></summary><p class="guest-local">Baixe um convite individual, envie o arquivo e importe a confirmação recebida em “Respostas que chegaram”. Sua lista fica neste aparelho.</p><p class="email-local-note">E-mail individual: adicione o endereço e baixe um rascunho com o convite anexado. Você confere e envia pelo seu programa de e-mail. Envio automático será conectado junto da hospedagem.</p><div class="guest-add"><div class="field"><label for="guest-name">Nome no convite</label><input id="guest-name" maxlength="80" placeholder="Ex.: Família Silva"></div><div class="field"><label for="guest-email">E-mail do convidado (opcional)</label><input id="guest-email" type="email" maxlength="254" placeholder="nome@exemplo.com"></div><div class="field"><label for="guest-party">Pessoas no convite</label><select id="guest-party"></select></div><button class="add-guest" type="button">Adicionar à lista</button></div><details class="bulk-guests"><summary>Adicionar vários nomes de uma vez</summary><label for="bulk-guest-names">Um convidado por linha. Opcional: nome; e-mail</label><textarea id="bulk-guest-names" rows="4" maxlength="8100" placeholder="Ana e João\nFamília Silva\nDona Lúcia"></textarea><button class="add-bulk-guests" type="button">Adicionar nomes</button></details><div class="guest-stats" role="status"></div><div class="guest-list"></div><p class="guest-empty">Sua lista começa com alguém especial. Adicione o primeiro nome acima.</p>';
 document.querySelector('#invite-fields').after(panel);const $=s=>panel.querySelector(s);for(let count=1;count<=10;count++)$('#guest-party').add(new Option(String(count),String(count)));
 function add(names,count=1){const guests=cleanGuests(getState().guests),known=new Set(guests.map(guest=>guest.name.toLocaleLowerCase('pt-BR')));let added=0;for(const raw of names){const [rawName,rawEmail]=raw.split(';'),name=rawName.trim(),email=(rawEmail||'').trim();if(!name||name.length>80||known.has(name.toLocaleLowerCase('pt-BR')))continue;if(guests.length>=100)break;guests.push({id:crypto.randomUUID(),name,email:validGuestEmail(email)?email:'',allowedCount:count,status:'invited',attendingCount:0});known.add(name.toLocaleLowerCase('pt-BR'));added++;}onChange({guests});toast(added?added+(added===1?' convite na sua lista.':' convites na sua lista.'):'Confira os nomes. Há um limite de 100 convites, sem nomes repetidos.');return added;}
 $('.add-guest').addEventListener('click',()=>{if(!$('#guest-name').value.trim()){$('#guest-name').focus();toast('Escreva um nome para o convite.');return;}if($('#guest-email').value&&!validGuestEmail($('#guest-email').value)){toast('Confira o e-mail antes de adicionar.');$('#guest-email').focus();return;}if(add([$('#guest-name').value+';'+$('#guest-email').value],Number($('#guest-party').value)))$('#guest-name').value='';});
 $('.add-bulk-guests').addEventListener('click',()=>{if(add($('#bulk-guest-names').value.split(/\r?\n/)))$('#bulk-guest-names').value='';});
 let lastRendered='';
 function render(){panel.hidden=getState().format!=='convite';const guests=cleanGuests(getState().guests),key=JSON.stringify(guests);if(key===lastRendered)return;lastRendered=key;$('.guest-count').textContent=guests.length+'/100';$('.guest-empty').hidden=!!guests.length;$('.add-guest').disabled=guests.length>=100;$('.add-bulk-guests').disabled=guests.length>=100;const accepted=guests.filter(guest=>guest.status==='accepted'),declined=guests.filter(guest=>guest.status==='declined');$('.guest-stats').textContent=guests.length?accepted.reduce((total,guest)=>total+guest.attendingCount,0)+' presenças · '+(guests.length-accepted.length-declined.length)+' respostas pendentes · lista local':'';const list=$('.guest-list');list.replaceChildren();for(const guest of guests){const row=document.createElement('article');row.className='guest-row';const copy=document.createElement('div'),name=document.createElement('strong'),status=document.createElement('span');name.textContent=guest.name;status.textContent=guest.status==='accepted'?guest.attendingCount+' '+(guest.attendingCount===1?'presença':'presenças')+' confirmada'+(guest.attendingCount===1?'':'s')+' neste aparelho':guest.status==='declined'?'Não poderá ir · resposta importada':'Até '+guest.allowedCount+' '+(guest.allowedCount===1?'pessoa':'pessoas')+' · sem resposta';copy.append(name,status);const preview=document.createElement('button');preview.type='button';preview.textContent='Ver convite';preview.setAttribute('aria-label','Ver convite de '+guest.name);preview.addEventListener('click',()=>onPreview(guest));const remove=document.createElement('button');remove.type='button';remove.className='guest-remove';remove.textContent='×';remove.setAttribute('aria-label','Remover '+guest.name+' da lista');remove.addEventListener('click',()=>onChange({guests:guests.filter(item=>item.id!==guest.id)}));const download=document.createElement('button');download.type='button';download.className='download-guest-invitation';download.textContent='Baixar convite';download.setAttribute('aria-label','Baixar convite de '+guest.name);download.addEventListener('click',async()=>{download.disabled=true;try{await onDownload(guest);toast('Convite de '+guest.name+' baixado.');}catch{toast('Não foi possível preparar o convite agora.');}finally{download.disabled=false;}});const emailInput=document.createElement('input');emailInput.type='email';emailInput.className='guest-email-edit';emailInput.value=guest.email||'';emailInput.placeholder='E-mail (opcional)';emailInput.setAttribute('aria-label','E-mail de '+guest.name);emailInput.addEventListener('change',()=>{if(emailInput.value&&!validGuestEmail(emailInput.value)){toast('Confira o endereço de e-mail.');return;}onChange({guests:guests.map(item=>item.id===guest.id?{...item,email:emailInput.value.trim()}:item)});});copy.append(emailInput);const emailButton=document.createElement('button');emailButton.type='button';emailButton.className='guest-email-draft';emailButton.textContent='Preparar e-mail';emailButton.disabled=!guest.email;emailButton.setAttribute('aria-label','Preparar e-mail para '+guest.name);emailButton.addEventListener('click',async()=>{emailButton.disabled=true;try{await onEmail(guest);toast('Rascunho com convite anexado baixado. Abra no seu programa de e-mail, confira e envie.');}catch(error){toast(error.message||'Não foi possível preparar o e-mail.');}finally{emailButton.disabled=false;}});row.append(copy,preview,download,emailButton,remove);list.append(row);}}
 render();return {render,reply({id,status,count}){const guests=cleanGuests(getState().guests),guest=guests.find(item=>item.id===id);if(!guest||!['accepted','declined'].includes(status)||!Number.isInteger(count)||count<0||count>guest.allowedCount||(status==='accepted'&&count<1))return false;guest.status=status;guest.attendingCount=status==='declined'?0:count;onChange({guests});return true;}};
}
